/*
 * A192585  Monotonic ordering of set S generated by these rules: if x and y
 *          are in S and xy+1 is a prime, then xy+1 is in S, and 2, 5, 8, 11,
 *          and 14 are in S.
 * https://oeis.org/A192585
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, fini, full
 * Formula:   not stated
 * Range:     u8 n <= 6, u16 n <= 28, u32 n <= 70, u64 n <= 70, u128 n <= 70,
 *            big any n
 * Validated: full, pass, 70 terms through n = 70 (2026-11-03)
 * Helpers:   is_prime_u128, is_prime_u64, mem
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Sequence A192585:  monotonic closure of {2,5,8,11,14} under x·y+1 prime */
#include <stdlib.h>
#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>
#include <limits.h>
#include "../utils/is_prime_u128.h"
#include "../utils/is_prime_u64.h"
#include "../utils/mem.h"

/* -----------------  Generic primality test ------------------------ */
static bool isPrimeGeneric(seq_t n)
{
    /* all seq_t are unsigned; use the smallest type that fits */
    if ((seq_t)(ULLONG_MAX) >= n) {
        return is_prime_u64((uint64_t)n);
    }
#if defined(__SIZEOF_INT128__)
    return is_prime_u128((__uint128_t)n);
#else
    /* fallback: if seq_t > 64‑bit but no 128‑bit support,
       order the test as simple trial division up to sqrt */
    seq_t limit = 0;
    for (seq_t i = 2; i*i <= n; ++i) {
        if (n % i == 0) return false;
    }
    return true;
#endif
}

static int compare_seq_t(const void *a, const void *b)
{
    const seq_t *x = (const seq_t *)a;
    const seq_t *y = (const seq_t *)b;
    if (*x < *y) return -1;
    if (*x > *y) return 1;
    return 0;
}

static seq_t S[80];      /* enough to hold all 70 terms */
static size_t sz = 0;    /* number of elements actually stored */
static bool initialized = false;

/* simple linear search for presence of a value in S */
static bool contains(seq_t v) {
    for (size_t i = 0; i < sz; ++i) {
        if (S[i] == v) return true;
    }
    return false;
}

/* initialise the sequence once */
static void make_sequence(void) {
    if (initialized) return;
    initialized = true;

    /* initial seeds */
    S[0] = (seq_t)2;
    S[1] = (seq_t)5;
    S[2] = (seq_t)8;
    S[3] = (seq_t)11;
    S[4] = (seq_t)14;
    sz = 5;

    bool changed = true;
    while (changed) {
        changed = false;
        size_t cur_sz = sz;
        for (size_t i = 0; i < cur_sz; ++i) {
            for (size_t j = i; j < cur_sz; ++j) {
                /* using 64‑bit arithmetic: products fit in 64 bits for this problem */
                uint64_t prod = (uint64_t)S[i] * (uint64_t)S[j] + 1ULL;
                seq_t val = (seq_t)prod;
                if (!isPrimeGeneric(val)) continue;
                if (!contains(val)) {
                    S[sz++] = val;
                    changed = true;
                }
            }
        }
    }

    mem_qsort(S, sz, sizeof(seq_t), compare_seq_t);
}

seq_t a(idx_t n)
{
    if (n == 0) return 0;          /* undefined for offset below 1 */
    make_sequence();
    if (n <= (idx_t)sz) return S[n - 1];
    return 0;                       /* undefined beyond the finite sequence */
}
